def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Extract opponent history
    op = [h[1] for h in history]
    my = [h[0] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_c = my.count('C')

    # Detect always defect / near always defect
    if op_d >= n - 1 and n >= 4:
        return 'D'
    if n >= 8 and op_d * 4 >= n * 3:
        return 'D'

    # Detect always cooperate / near always cooperate
    if op_d == 0:
        # Exploit near the end; cooperate to maintain score otherwise
        if n >= 93:
            return 'D'
        return 'C'

    # Current streak of opponent defections
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break

    # Current streak of opponent cooperations
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_c += 1
        else:
            break

    # Endgame exploitation: if opponent is mostly cooperative, defect late
    remaining = 100 - n
    if remaining <= 3:
        if op_c * 2 >= n:
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    if remaining <= 8:
        if op_c * 3 >= n * 2:
            return 'D'
        if streak_d >= 2:
            return 'D'
        return 'C' if op[-1] == 'C' else 'D'

    # If opponent is mostly cooperative, cooperate but occasionally test
    if op_d * 5 <= n:
        if n >= 20 and n % 19 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # If opponent is heavily defecting, defect
    if op_d * 2 >= n:
        if streak_d >= 1:
            return 'D'
        # Maybe they just defected once; retaliate
        return 'D'

    last_op = op[-1]
    last_my = my[-1]

    # Tit-for-tat with forgiveness
    if last_op == 'D':
        # If they just defected once, retaliate once
        if streak_d == 1:
            return 'D'
        # If they defected a few times, retaliate but try to break out
        if streak_d == 2:
            return 'D' if rng.random() < 0.8 else 'C'
        # Long defection streak: defect hard
        return 'D'

    # Opponent just cooperated
    if streak_c >= 1:
        # If we defected previously and they cooperated, continue cooperating to rebuild
        if last_my == 'D':
            return 'C'
        # Occasional probing defect when mutual cooperation is stable
        if n >= 15 and streak_c >= 4 and rng.random() < 0.04:
            return 'D'
        return 'C'

    return 'C'
